  rs.forEach((r,i)=>{const p=.5+.5*Math.sin(t*3-i*.9);r.style.opacity=seg(t,.2,.6)*o*(.35+.65*p);r.style.transform='scale('+(.85+.2*p)+')';r.style.borderColor=p>.6?'#0EBE02':'#BFE9BB'});
