  const upd=(P,ox)=>P.forEach((p,i)=>{p.setAttribute('d',arc(13.5+ox+dx,24,R,DEF[i][0]+rot*(i%2?-.6:1),DEF[i][1]+rot*(i%2?-.6:1)))});
